  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B004",
        "laureates": [
          "David Vanderbilt",
          "Georg Kresse",
          "Peter E. Blöchl"
        ],
        "citation": "For the development of ultrasoft pseudopotentials and the projector augmented-wave method, which made accurate first-principles calculations of materials broadly practical."
      }
    ]
  },
  "alternatives": [
    "B031",
    "B025"
  ],
  "statement": {
    "case_for": "B004 recognizes a durable advance in how physicists calculate real materials from first principles. Ultrasoft pseudopotentials and the projector augmented-wave method made calculations more efficient while retaining accuracy, enabling broad, sustained use in condensed-matter research. The complementary contributions of Vanderbilt, Kresse, and Blöchl offer a focused basis for credit, and decades of validation support the achievement's maturity.",
    "case_against": "The methods grew from a wider history of pseudopotential and electronic-structure work, and their linked development and implementation make the precise boundaries of individual credit important. Their impact is chiefly through enabling research, so the citation must identify the methodological advance clearly rather than imply a single isolated discovery.",
    "responses": [
      {
        "member_id": "kroll-stefan",
        "point": "Kroll argues that Katori and Ye independently developed leading optical lattice clock approaches, establishing a mature instrument with important scientific applications.",
        "response": "I agree that B031 is an exceptionally strong and mature candidate, and list it as an alternative. Its case rests on a clear measurement advance. I favor B004 because the methods have become broadly enabling across first-principles materials physics, with a long record of independent use and validation."
      },
      {
        "member_id": "olsson-eva",
        "point": "Olsson argues that spherical-aberration correction transformed electron microscopy, while noting that the relative credit for theoretical design, practical implementation, and demonstration needs careful historical review.",
        "response": "That is a compelling instrument achievement and a reasonable alternative. The attribution question she identifies is also present in B004, but here the distinct contributions to the methods and their computational realization support a coherent account. I would want both histories examined carefully before a final award."
      },
      {
        "member_id": "pearce-mark",
        "point": "Pearce describes squeezed light as a mature technique that has delivered measurable sensitivity gains in operating gravitational-wave detectors, while urging care in distinguishing theory from later implementation.",
        "response": "The demonstrated detector gains make B008 a strong case, and I agree that the stages of contribution should not be conflated. I give greater weight to B004's long-established role across materials research; in either case, the citation should distinguish the foundational advance from its later practical deployment."
      }
    ],
    "uncertainties": [
      "The historical boundary between earlier pseudopotential developments and the specific advances due to Vanderbilt, Kresse, and Blöchl needs careful review.",
      "The relative weight of method invention, implementation, and dissemination in the proposed credit should be checked."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
